/**
 * emit to subscription queries of type FindCase_,
 * but only if the id matches
 *
 * @param		entity	Case_
 */
	protected void emitFindCase_( Case_ entity ) {
		LOGGER.info("handling emitFindCase_" );
		
	    queryUpdateEmitter.emit(FindCase_Query.class,
	                            query -> query.getFilter().getCase_Id().equals(entity.getCase_Id()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllCase_
	 * 
	 * @param		entity	Case_
	 */
	protected void emitFindAllCase_( Case_ entity ) {
		LOGGER.info("handling emitFindAllCase_" );
		
	    queryUpdateEmitter.emit(FindAllCase_Query.class,
	                            query -> true,
	                            entity);
	}

